"""Export the schema generated by the actual FastAPI routes (no DB access required)."""

import json
from pathlib import Path

from backend.app import create_app

root = Path(__file__).resolve().parents[1]
schema = create_app().openapi()
operations = sum(
    method in {"get", "post", "patch", "put", "delete"}
    for path in schema["paths"].values()
    for method in path
)
(root / "docs/api.openapi.json").write_text(
    json.dumps(schema, ensure_ascii=False, indent=2) + "\n",
    encoding="utf-8",
)
print(f"Exported {operations} real operations on {len(schema['paths'])} paths")
